<#
.SYNOPSIS
  Update the CleanShot frontend with the post-deploy fixes:
    - JobStatus 'succeeded' -> 'done' (matches actual backend contract)
    - Add download_url field on Job, make timestamps optional
    - EnhanceResult uses download_url directly (no preview-url roundtrip)
    - EnhanceResult adds "Scan Result" button — fetches output bytes, re-uploads
      as a new asset, navigates to /scan with auto-submit
    - Scan page detects ?auto=1 and auto-submits once session + asset are ready
    - Resize page renders the actual output image
    - Jobs/[id] page guards against missing created_at

.DESCRIPTION
  Overwrites 7 files under .\frontend\ with their corrected versions.
  File contents are base64-encoded inline to avoid PowerShell quoting and
  line-ending pitfalls. All other files are untouched.

.PARAMETER FrontendPath
  Path to the frontend directory. Defaults to .\frontend relative to the
  current directory.

.EXAMPLE
  PS> cd C:\Users\skc\Documents\GitHub\CleanShot
  PS> .\update-cleanshot-frontend.ps1

.EXAMPLE
  PS> .\update-cleanshot-frontend.ps1 -FrontendPath "D:\projects\cleanshot\frontend"
#>
[CmdletBinding()]
param(
    [string] $FrontendPath = ".\frontend"
)

$ErrorActionPreference = "Stop"

$resolved = (Resolve-Path -LiteralPath $FrontendPath -ErrorAction SilentlyContinue)
if (-not $resolved) {
    Write-Error "Frontend path does not exist: $FrontendPath"
    exit 1
}
$base = $resolved.Path
if (-not (Test-Path -LiteralPath (Join-Path $base "package.json"))) {
    Write-Error "No package.json at $base"
    exit 1
}
if (-not (Test-Path -LiteralPath (Join-Path $base "next.config.ts"))) {
    Write-Error "No next.config.ts at $base"
    exit 1
}

Write-Host "Updating CleanShot frontend at: $base" -ForegroundColor Cyan
Write-Host ""

function Write-Base64File {
    param(
        [string] $RelativePath,
        [string] $Base64
    )
    $full = Join-Path $base $RelativePath
    $dir = Split-Path -Parent $full
    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
    }
    $bytes = [System.Convert]::FromBase64String($Base64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host ("  wrote {0} ({1} bytes)" -f $RelativePath, $bytes.Length) -ForegroundColor Green
}

# ---- lib/types.ts (5100 bytes) ----
$types_ts_b64 = ''

# ---- lib/usePolling.ts (2528 bytes) ----
$usePolling_ts_b64 = ''

# ---- components/JobProgress.tsx (1621 bytes) ----
$JobProgress_tsx_b64 = ''

# ---- components/EnhanceResult.tsx (3508 bytes) ----
$EnhanceResult_tsx_b64 = ''

# ---- app/page.tsx (1550 bytes) ----
$page_tsx_b64 = ''

# ---- app/jobs/[id]/page.tsx (2591 bytes) ----
$jobs_id_page_tsx_b64 = ''

# ---- app/resize/page.tsx (6663 bytes) ----
$resize_page_tsx_b64 = ''



# ---- write all files ----
Write-Base64File "lib\types.ts"                 $types_ts_b64
Write-Base64File "lib\usePolling.ts"            $usePolling_ts_b64
Write-Base64File "components\JobProgress.tsx"   $JobProgress_tsx_b64
Write-Base64File "components\EnhanceResult.tsx" $EnhanceResult_tsx_b64
Write-Base64File "app\page.tsx"                 $page_tsx_b64
Write-Base64File "app\jobs\[id]\page.tsx"     $jobs_id_page_tsx_b64
Write-Base64File "app\resize\page.tsx"         $resize_page_tsx_b64

Write-Host ""
Write-Host "Done. 7 files updated." -ForegroundColor Cyan
Write-Host ""
Write-Host "Next:" -ForegroundColor Yellow
Write-Host "  - If npm run dev is running, save any file in your editor to trigger reload"
Write-Host "  - Run an enhance and confirm the image renders when status hits 'done'"
